import React, { useState, useEffect, useRef } from 'react';
import { Chart } from 'chart.js/auto';
import './SlideBarComponent.scss';

const SlideBarComponent = () => {
    const [incomeDropdownOpen, setIncomeDropdownOpen] = useState(false);
    const [leaveDropdownOpen, setLeaveDropdownOpen] = useState(false);
    const [benefitDropdownOpen, setBenefitDropdownOpen] = useState(false);
    const [activeView, setActiveView] = useState('dashboard');

    const doughnutRef = useRef(null);
    const chartInstanceRef = useRef(null);

    const toggleIncomeDropdown = () => setIncomeDropdownOpen(!incomeDropdownOpen);
    const toggleLeaveDropdown = () => setLeaveDropdownOpen(!leaveDropdownOpen);
    const toggleBenefitDropdown = () => setBenefitDropdownOpen(!benefitDropdownOpen);

    useEffect(() => {
        if (activeView === 'incomeByShareholder' && doughnutRef.current) {
            // Hủy chart cũ nếu có
            if (chartInstanceRef.current) {
                chartInstanceRef.current.destroy();
            }

            // Tạo chart mới
            chartInstanceRef.current = new Chart(doughnutRef.current, {
                type: 'doughnut',
                data: {
                    labels: ['Social', 'Search Engines', 'Direct', 'Other'],
                    datasets: [{
                        data: [260, 125, 54, 146],
                        backgroundColor: [
                            '#0d6efd', // primary
                            '#198754', // success
                            '#ffc107', // warning
                            '#dee2e6'  // gray
                        ],
                        borderColor: 'transparent'
                    }]
                },
                options: {
                    maintainAspectRatio: false,
                    cutout: '65%',
                }
            });
        }
    }, [activeView]);

    return (
        <div className="sidebar">
            <div className="sidebar-menu">
                <div className="active">
                    <a href="#" onClick={() => setActiveView('dashboard')}>
                        <i className="bi bi-house-door"></i> Dashboard
                    </a>
                </div>

                <div>
                    <a href="#" onClick={() => setActiveView('messages')}>
                        <i className="bi bi-envelope"></i> Messages
                    </a>
                </div>

                <div>
                    <a href="#" className="dropdown-toggle" onClick={toggleIncomeDropdown}>
                        <i className="bi bi-currency-dollar"></i> Tổng thu nhập
                        <i className={`bi bi-chevron-down dropdown-icon ${incomeDropdownOpen ? 'rotate' : ''}`}></i>
                    </a>
                    {incomeDropdownOpen && (
                        <ul className="submenu">
                            <li><a href="#" onClick={() => setActiveView('incomeByShareholder')}>Theo cổ đông</a></li>
                            <li><a href="#" onClick={() => setActiveView('incomeByGender')}>Theo giới tính</a></li>
                        </ul>
                    )}
                </div>

                {/* Các menu khác giữ nguyên */}
                <div>
                    <a href="#"><i className="bi bi-box-arrow-right"></i> Logout</a>
                </div>
            </div>

            {/* Main view hiển thị */}
            <div className="main-view">
                {activeView === 'dashboard' && <h2>Dashboard</h2>}

                {activeView === 'incomeByShareholder' && (
                    <div>
                        <h2>Thống kê thu nhập theo cổ đông</h2>
                        <div style={{ width: '100%', height: '300px' }}>
                            <canvas ref={doughnutRef}></canvas>
                        </div>
                    </div>
                )}

                {activeView === 'incomeByGender' && (
                    <div>
                        <h2>Thống kê thu nhập theo giới tính</h2>
                        <p>Hiển thị dữ liệu hoặc biểu đồ ở đây...</p>
                    </div>
                )}

                {activeView === 'messages' && (
                    <div>
                        <h2>Messages</h2>
                        <p>Hiển thị tin nhắn ở đây...</p>
                    </div>
                )}
            </div>
        </div>
    );
};

export default SlideBarComponent;
